// Получаем сообщение от пользователя
const message = $input.first().json.message;
const userId = message.from.id;
const userName = message.from.first_name;
const text = message.text || '';
const chatId = message.chat.id;

console.log('Received message from', userName, ':', text);

// Обрабатываем команды
if (text.startsWith('/start')) {
  return {
    json: {
      command: 'start',
      user_id: userId,
      user_name: userName,
      chat_id: chatId
    }
  };
}

if (text.startsWith('/search') || text.includes('найти') || text.includes('поиск')) {
  // Извлекаем категорию из текста
  const category = text.replace('/search', '').replace('найти', '').replace('поиск', '').trim();

  return {
    json: {
      command: 'search',
      user_id: userId,
      user_name: userName,
      chat_id: chatId,
      category: category || 'wireless headphones',
      moq: 'any',
      price_range: 'any',
      timestamp: new Date().toISOString()
    }
  };
}

if (text.startsWith('/help')) {
  return {
    json: {
      command: 'help',
      user_id: userId,
      user_name: userName,
      chat_id: chatId
    }
  };
}

// По умолчанию считаем что это поисковый запрос
return {
  json: {
    command: 'search',
    user_id: userId,
    user_name: userName,
    chat_id: chatId,
    category: text,
    moq: 'any',
    price_range: 'any',
    timestamp: new Date().toISOString()
  }
};

