// Парсим AI ответ
const item = $input.first().json;
let aiData = {};

try {
  let aiResponse = item.response || item.text || '{}';
  if (typeof aiResponse === 'string') {
    aiResponse = aiResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    aiData = JSON.parse(aiResponse);
  } else {
    aiData = aiResponse;
  }
} catch (error) {
  aiData = {
    reliability_score: 7,
    recommended: true,
    summary_ru: 'Надёжная компания',
    pros: ['Проверенный поставщик'],
    risks: ['Нет данных']
  };
}

return {
  json: {
    chat_id: item.chat_id,
    company_name: item.company_name,
    rating: item.rating,
    moq: item.moq,
    price: item.price,
    location: item.location,
    email: item.contact_email,
    url: item.company_url,
    ai_score: aiData.reliability_score || 7,
    recommended: aiData.recommended !== false,
    summary: aiData.summary_ru || 'Нет данных',
    pros: Array.isArray(aiData.pros) ? aiData.pros.join(', ') : 'Нет данных',
    risks: Array.isArray(aiData.risks) ? aiData.risks.join(', ') : 'Нет данных'
  }
};

// Собираем результаты
const items = $input.all();
const chatId = items[0].json.chat_id;

// Группируем по chat_id
const leads = items.map(item => item.json);
leads.sort((a, b) => b.ai_score - a.ai_score);

// Формируем сообщение
let message = `✅ **НАЙДЕНО ${leads.length} ПОСТАВЩИКОВ**\n\n📊 Отсортировано по надёжности\n\n`;
message += `━━━━━━━━━━━━━━━━━━━━\n\n`;

leads.forEach((lead, index) => {
  const number = index + 1;
  const emoji = lead.recommended ? '✅' : '⚠️';

  message += `🏢 **#${number}: ${lead.company_name}**\n`;
  message += `⭐️ Рейтинг: ${lead.rating}/5\n`;
  message += `📊 AI-оценка: ${lead.ai_score}/10\n`;
  message += `${emoji} ${lead.recommended ? 'Рекомендуется' : 'Требует проверки'}\n\n`;
  message += `📍 ${lead.location}\n`;
  message += `📦 MOQ: ${lead.moq}\n`;
  message += `💰 Цена: $${lead.price}\n\n`;
  message += `📧 ${lead.email}\n`;
  message += `🌐 ${lead.url}\n\n`;
  message += `💬 **Резюме AI:**\n${lead.summary}\n\n`;
  message += `✅ **Плюсы:** ${lead.pros}\n`;
  message += `⚠️ **Риски:** ${lead.risks}\n\n`;
  message += `━━━━━━━━━━━━━━━━━━━━\n\n`;
});

message += `🎯 Осталось поисков: 4\n`;
message += `💎 Хотите больше? /upgrade`;

return {
  json: {
    chat_id: chatId,
    message: message
  }
};
